function getProduction(iid){let d=db.productionPlans.find(x=>x.interviewId==iid);if(!d){d={id:id(),interviewId:iid,status:'未开始',locked:false,updatedAt:'',roles:{executiveProducer:'Angeline',director:'',host:'Angeline',cinematographer:'',audio:'',dataManager:''},sections:{}};db.productionPlans.push(d)}d.sections=d.sections||{};d.roles=d.roles||{};return d}
function productionCompletion(d){let done=productionSections.filter(([k])=>(d.sections?.[k]?.content||'').trim()).length;return Math.round(done/productionSections.length*100)}
function productionPrompt(k){return {
dashboard:'列出本次拍摄的故事 KPI、六个角色、导演目标、必拍故事、危险区域和 Ending。',
timeline:'按 T-24、出发、到场、布光、收音、访谈、B-roll、Wrap、双备份、Cloud Queue、Review 编排。',
preflight:'确认地点、停车、联系人、电话、临时变动、施工／会议／噪音、天气、交通和备用路线。',
equipment:'按 Camera、Audio、Lighting、Production、Emergency Kit 列出数量、负责人和装箱状态。',
arrival:'记录现场光线、窗户、Logo、员工、声音、客户、最佳背景、不可用背景和场景地图。',
camera:'明确 A/B/C Camera 任务，并列出 Opening、Interview、Reaction、B-roll、Ending 必拍镜头。',
audio:'记录主备麦、录音机、采样率、双录、监听、回声、空调噪音、施工噪音和停止拍摄条件。',
lighting:'记录主灯、补光、背光、Catch Light、背景层次、Logo 可见性、肤色、窗户曝光和反光。',
host:'记录暖场话题、开场动作、Rolling Protocol、主持人任务和正式结束后的继续聊天计划。',
quality:'设计每十分钟 QC 节点，并指定由谁检查焦点、曝光、收音、电池、容量、过热和录制状态。',
rescue:'为紧张、官方、卖产品、回答过短、跑题分别写出触发条件和现场救场话术。',
wrap:'列出结束后继续录制五分钟、补拍环境、Logo、走路、产品、办公室、空镜和现场灵感记录。',
backup:'写清三份副本、两种介质、一份异地的路径、责任人、校验方法和离场前完成标准。',
metadata:'建立文件命名规则、卡号、时长、精彩时间点、技术问题、补拍需求和剪辑交接说明。',
kpi:'分别给故事完整度、情绪、收音、画面、B-roll、可用内容、商业价值、二次采访价值评分与改进。'}[k]||''}
function productionWorkspace(iid){let x=interview(iid),p=person(x?.personId),d=getProduction(iid);save();modal(`拍摄系统 · ${esc(p?.name||'')}`,`<div class="workspace-head"><div><b>${esc(x?.topic||'未命名节目')}</b><span>${esc(p?.name||'')} · ${esc(p?.company||'')}</span></div><div>${stagePill(d.status||'未开始')} <span class="pill">完成度 ${productionCompletion(d)}%</span> ${d.locked?'<span class="pill status-complete">拍摄执行版已锁定</span>':''}</div></div><div class="strategy-gate production-gate"><b>Production Department KPI：故事是否完整带回</b><span>画面漂亮不是唯一标准；声音、故事节点、B-roll、备份和素材登记缺一不可。</span></div><div class="role-strip">${[['executiveProducer','总制片'],['director','导演'],['host','主持人'],['cinematographer','摄影'],['audio','收音'],['dataManager','素材管理员']].map(([k,l])=>`<label><span>${l}</span><input data-role="${k}" value="${esc(d.roles[k]||'')}"></label>`).join('')}</div><div class="intel-workspace"><aside class="intel-stepnav">${productionSections.map(([k,t],idx)=>`<button class="${idx===0?'active':''}" data-production-tab="${k}"><i>${String(idx+1).padStart(2,'0')}</i><span>${t}</span><b>${d.sections?.[k]?.content?'✓':''}</b></button>`).join('')}</aside><section id="productionbody" class="intel-body"></section></div><div class="formactions"><button class="btn" data-production-status>更新拍摄状态</button><button class="btn ${d.locked?'':'primary'}" data-lockproduction>${d.locked?'解除执行版锁定':'锁定拍摄执行版'}</button></div>`);
 function show(k){$$('[data-production-tab]').forEach(b=>b.classList.toggle('active',b.dataset.productionTab===k));let meta=productionSections.find(a=>a[0]===k),sec=d.sections[k]||{};$('#productionbody').innerHTML=`<div class="intel-sectionhead"><div><span>${meta[1]}</span><p>${meta[2]}</p></div><div class="intel-badges"><span>${esc(sec.status||'未开始')}</span><span>${esc(sec.owner||'待分配')}</span></div></div><form id="productionForm"><div class="formgrid">${field('status','模块状态',sec.status||'未开始','select',false,['未开始','准备中','待确认','现场可执行','已完成','需补拍'])}${field('owner','主要负责人',sec.owner||'待分配','select',false,['待分配','总制片','导演','主持人','摄影','收音','素材管理员','全体'])}${field('content','执行方案 / 检查清单',sec.content||'','textarea',true,[],productionPrompt(k))}${field('trigger','时间 / 检查节点',sec.trigger||'','textarea',true,[],'例如 T-24；到场后；每 10 分钟；离场前')}${field('actions','现场动作 / 停止条件 / 备用方案',sec.actions||'','textarea',true)}${field('risks','技术问题、遗漏风险与补拍需求',sec.risks||'','textarea',true)}</div><div class="formactions"><button class="btn primary">保存本模块</button></div></form>`;$('#productionForm').onsubmit=e=>{e.preventDefault();d.sections[k]=Object.fromEntries(new FormData(e.target));d.updatedAt=new Date().toLocaleDateString('en-SG');if(d.status==='未开始')d.status='拍摄准备中';save();toast('拍摄模块已保存');show(k)}}
 $$('[data-production-tab]').forEach(b=>b.onclick=()=>show(b.dataset.productionTab));$$('[data-role]').forEach(el=>el.onchange=e=>{d.roles[e.target.dataset.role]=e.target.value;save();toast('角色分工已保存')});$('[data-production-status]').onclick=()=>{d.status=d.status==='现场可执行'?'拍摄准备中':'现场可执行';d.updatedAt=new Date().toLocaleDateString('en-SG');save();close();productionWorkspace(iid)};$('[data-lockproduction]').onclick=()=>{if(!d.locked&&productionCompletion(d)<70&&!confirm(`当前拍摄系统完成度只有 ${productionCompletion(d)}%，仍要锁定拍摄执行版吗？`))return;d.locked=!d.locked;d.updatedAt=new Date().toLocaleDateString('en-SG');save();close();productionWorkspace(iid)};show('dashboard')}
