 dashboard:{main:'本期内容价值总览',ref:'关键结论与下一步',platform:'当前审核状态与负责人',review:'风险、缺口与必须补充'},
 ingest:{main:'素材清单与完整性',ref:'文件路径、时长与技术参数',platform:'缺失素材与补拍项目',review:'备份状态与导入异常'},
 understanding:{main:'整场访谈价值分析',ref:'关键时间码与原文依据',platform:'适合产出的内容方向',review:'待核验事实与敏感信息'},
 transcript:{main:'转录分段与内容分类',ref:'时间码、说话人及段落编号',platform:'故事／观点／数据／风险标签',review:'错字、姓名、数字与术语核验'},
