// V53 采访工作台：策划总表 + 主持人路线 + 摄像清单 + 拍前检查 + 拍后归档
function completion(x){
 const basic=['researchGap','topic','coverTitle','audience','painPoint','memoryPoint','hook3s','opening','corePromise','shootDate','location'];
 let n=basic.filter(k=>String(x[k]||'').trim()).length;
 let routes=(x.routeRows||[]).filter(r=>r.question||r.goal).length;
 let prep=(x.preflightChecks||[]).filter(r=>r.done).length;
 return Math.min(100,Math.round((n+Math.min(routes,5)+Math.min(prep,4))/(basic.length+9)*100));
}

function prepReadiness(x){
 ensureScriptShape(x);
 const checks=x.preflightChecks||[];
 const done=checks.filter(r=>r.done).length;
 const total=checks.length;
 const equipment=x.equipmentChecks||[];
 const equipmentReady=equipment.length>0&&equipment.every(r=>r.status==='已检查');
 const hasProblem=equipment.some(r=>r.status==='有问题');
 const pct=total?Math.round(done/total*100):0;
 const ready=total>0&&done===total&&equipmentReady&&!hasProblem;
 return {done,total,pct,ready,equipmentReady,hasProblem};
}
function prepBadge(x){
 const r=prepReadiness(x);
 if(r.ready)return `<div class="prep-readiness ready"><b>✓ 已准备好</b><span>${r.done}/${r.total} · 设备已检查</span></div>`;
 if(r.hasProblem)return `<div class="prep-readiness problem"><b>设备有问题</b><span>${r.done}/${r.total} 项完成</span></div>`;
 return `<div class="prep-readiness pending"><div><b>${r.done}/${r.total}</b><span>${r.pct}%</span></div><i><em style="width:${r.pct}%"></em></i><small>${r.equipmentReady?'Checklist 尚未完成':'仍需完成拍前检查'}</small></div>`;
}

